const coords={shibuya:[110,490],'omote-sando':[180,445],gaiemmae:[245,398],'aoyama-itchome':[310,354],'akasaka-mitsuke':[375,345],'tameike-sanno':[415,404],toranomon:[474,457],shimbashi:[548,500],ginza:[610,450],kyobashi:[660,401],nihombashi:[713,355],mitsukoshimae:[695,300],kanda:[635,250],suehirocho:[633,196],'ueno-hirokoji':[650,142],ueno:[685,86],inaricho:[755,102],tawaramachi:[818,144],asakusa:[867,97],ogikubo:[50,190],'nakano-sakaue':[170,250],shinjuku:[215,295],'shinjuku-sanchome':[250,310],'yotsuya':[352,285],'kokkai-gijidomae':[420,380],kasumigaseki:[500,420],tokyo:[607,364],otemachi:[575,310],korakuen:[496,142],ikebukuro:[275,65],nakameguro:[155,550],ebisu:[230,520],roppongi:[345,465],hibiya:[540,420],'higashi-ginza':[640,473],tsukiji:[700,493],kayabacho:[755,385],akihabara:[669,216],'kita-senju':[845,40],nakano:[110,210],takadanobaba:[225,167],waseda:[300,166],kagurazaka:[380,178],iidabashi:[428,188],kudanshita:[460,230],takebashi:[510,260],'nishi-funabashi':[915,430],'yoyogi-uehara':[77,410],'yoyogi-koen':[125,390],'meiji-jingumae':[165,411],nogizaka:[310,430],akasaka:[367,397],'nijubashimae':[540,350],yushima:[575,180],nezu:[560,100],sendagi:[570,60],'nishi-nippori':[610,40],ayase:[915,55],'kita-ayase':[930,22],wakoshi:[65,35],'kotake-mukaihara':[210,52],nagatacho:[410,330],sakuradamon:[475,365],yurakucho:[588,422],toyosu:[820,535],'shin-kiba':[930,545],hanzomon:[420,260],jimbocho:[512,219],'suitengumae':[775,340],'kiyosumi-shirakawa':[845,325],kinshicho:[882,210],oshiage:[922,130],meguro:[95,560],'azabu-juban':[353,520],komagome:[480,42],oji:[405,30],'akabane-iwabuchi':[280,20],honancho:[70,310],'nakano-fujimicho':[100,280],'nakano-shimbashi':[135,270]};
function pointsFor(stations){return stations.map((s,i)=>{if(coords[s.id])return coords[s.id];let a=i-1,b=i+1;while(a>=0&&!coords[stations[a].id])a--;while(b<stations.length&&!coords[stations[b].id])b++;const start=a>=0?coords[stations[a].id]:[50,80];const end=b<stations.length?coords[stations[b].id]:[910,510];const t=(i-a)/(b-a);return [start[0]+(end[0]-start[0])*t,start[1]+(end[1]-start[1])*t];});}
export function postcard(icon){return `<svg viewBox="0 0 240 150" aria-hidden="true">${symbols}<rect width="240" height="150" fill="#e9eddc"/><circle cx="183" cy="35" r="17" fill="#f5e8b7"/><path d="M0 105Q40 75 84 102T170 98T250 99V150H0" fill="#d5dfc0"/><path d="M0 130q65-25 125 0t125-6v26H0" fill="#c9d5b4"/><use href="#${icon}" x="68" y="21" width="104" height="104"/><path d="M44 130h152" stroke="#f5f3e4" stroke-width="3"/><circle cx="40" cy="85" r="15" fill="#bacba0"/><path d="M40 83v41" stroke="#9aa785" stroke-width="3"/><circle cx="206" cy="100" r="11" fill="#bfccaa"/></svg>`;}
export function renderMap(svg,{stations,index,visited,focus,layer,zoom,memory,onStation,onPoi,escape}){
 const pts=pointsFor(stations),current=pts[Math.min(index,pts.length-1)],center=pts[focus]||current;
 const width=960/zoom,height=590/zoom;svg.setAttribute('viewBox',`${Math.max(0,Math.min(960-width,center[0]-width/2))} ${Math.max(0,Math.min(590-height,center[1]-height/2))} ${width} ${height}`);
 const base=`<rect width="960" height="590" fill="#f0f2e7"/><rect width="960" height="590" fill="url(#blocks)"/><path d="M897-40C853 42 920 155 857 237S796 343 835 418S773 553 804 630" stroke="#bdD8d8" stroke-width="45" fill="none"/><path d="M-30 340L260 140 570 410 990 260M-30 480L390 80 930 520M100 650L290 350 640 60M-40 100L960 580" stroke="#fffdf3" stroke-width="12" fill="none"/><path d="M-30 340L260 140 570 410 990 260M-30 480L390 80 930 520M100 650L290 350 640 60M-40 100L960 580" stroke="#e1e5d4" stroke-width="1.5" fill="none"/><path d="M431 218q65-62 116 1l-20 113-80 12-44-73z" fill="#d9e3c7" stroke="#c3d5c1" stroke-width="10"/><path d="M602 22q55-33 92 8l-16 58-56 7zM75 323q70-26 85 16l-14 39-75-13z" fill="#dce5c8"/><text x="469" y="286" text-anchor="middle" fill="#9baa86" font-size="11">皇居 · 고쿄</text><use href="#palace" x="443" y="228" width="55" height="55"/><text x="55" y="160" class="district-label">新宿</text><text x="203" y="558" class="district-label">渋谷</text><text x="700" y="275" class="district-label">台東</text><text x="686" y="547" class="district-label">中央</text><text x="880" y="385" fill="#91b7b9" font-size="10" transform="rotate(73 880 385)" letter-spacing="3">SUMIDA RIVER · 隅田川</text>`;
 const path=pts.map(p=>p.join(',')).join(' ');
 const route=`<polyline points="${path}" stroke="#fffdf4" stroke-width="12" fill="none" stroke-linejoin="round"/><polyline points="${path}" stroke="var(--accent)" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
 const landmarkIds=stations.map((s,i)=>({s,i,p:places[s.id]})).filter(v=>v.p).filter((v,i,a)=>a.length<9||i%2===0||v.s.id==='asakusa');
 let pois=landmarkIds.map(({s,i,p},j)=>{const [x,y]=pts[i];const dx=x>800?-55:x<180?-25:j%2?34:-40,dy=y<110?36:-65;return `<g class="map-poi" data-poi="${i}" role="button" tabindex="0" aria-label="${escape(p.sight)}"><use href="#${p.icon}" x="${x+dx-22}" y="${y+dy-34}" width="48" height="48"/><text x="${x+dx+2}" y="${y+dy+26}" text-anchor="middle">${escape(layer==='food'?p.food:p.sight.split('와 ')[0])}</text>${layer==='food'?`<text x="${x+dx+2}" y="${y+dy+8}" text-anchor="middle" style="font-size:22px;stroke:none">${p.emoji}</text>`:''}</g>`;}).join('');
 const stops=stations.map((s,i)=>{const [x,y]=pts[i];const hide=memory&&i>=index;let labelY=i%2===0?-16:24;if(y<45)labelY=24;if(y>530)labelY=-16;return `<g class="map-stop ${visited.has(s.id)?'visited':''} ${i===index?'current':''}" data-station="${i}" tabindex="0" role="button" aria-label="${hide?'숨겨진 역':escape(s.ko)} 역 정보"><circle class="station-ring" cx="${x}" cy="${y}" r="${i===index?8:5}"/><text x="${x}" y="${y+labelY}" text-anchor="middle">${hide?'?':escape(s.ko)}</text></g>`;}).join('');
 const trainAt=pts[Math.max(0,Math.min(index-1,pts.length-1))],trainFrom=pts[Math.max(0,Math.min(index-2,pts.length-1))];
 const train=`<g transform="translate(${trainAt.join(' ')})" aria-label="여행 열차"><animateTransform attributeName="transform" type="translate" from="${trainFrom.join(' ')}" to="${trainAt.join(' ')}" dur=".6s" fill="freeze"/><g transform="translate(-10 -14)"><rect width="20" height="26" rx="6" fill="#214e41" stroke="#fffdf3" stroke-width="2"/><rect x="4" y="5" width="12" height="9" rx="2" fill="#e6edd8"/><circle cx="6" cy="19" r="2" fill="#eecb74"/><circle cx="14" cy="19" r="2" fill="#eecb74"/></g></g>`;
 svg.innerHTML=symbols+base+route+pois+stops+train;
 const bind=(selector,attr,fn)=>svg.querySelectorAll(selector).forEach(el=>{el.addEventListener('click',()=>fn(Number(el.dataset[attr])));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn(Number(el.dataset[attr]));}});});
 bind('[data-station]','station',onStation);bind('[data-poi]','poi',onPoi);
}
